// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Draft history"
// Changes: Draft history at the MCP message level: an agent lists a draft's named and safety snapshots, reads them
//          with every read tool, and cannot write to them.

import { describe, expect, it } from 'vitest'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { agentHarness } from './agentTestHarness'

const h = agentHarness()
const { call } = h

const data = (): ProjectData => ({
  ...defaultProjectData(),
  def: { nonterminals: 'E', terminals: 'id +', start: 'E' },
  ll: { grammar: 'E -> id\nE -> id + E', input: 'id + id' },
  names: { map: '', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
})

const FIXED = 'E -> id R\nR -> + E\nR -> eps'

/** A draft whose history has a named snapshot of the fixed grammar and a safety snapshot of a broken one. */
async function draftWithHistory() {
  const project = h.store.createProject('Výrazy', data())
  const { draft } = await call('create_draft', { project: project.id, label: 'Oprava' })
  const target = { kind: 'draft', id: draft.id }
  await call('set_grammar_rules', { target, text: FIXED })
  const named = h.store.createDraftSnapshot(draft.id, 'Opravená gramatika')
  await call('set_grammar_rules', { target, text: 'E -> id id' })
  if (named.status !== 'saved') throw new Error('no snapshot')
  h.store.restoreDraftSnapshot(draft.id, named.snapshot.id)
  return { project, draftId: draft.id as string, target }
}

describe("an agent reads a draft's history", () => {
  it('lists the named and safety snapshots of the draft, newest first, and none of them in the project history', async () => {
    const { project, target } = await draftWithHistory()
    const { snapshots } = await call('list_snapshots', { target })
    expect(snapshots.map((s: { kind: string; label: string }) => [s.kind, s.label])).toEqual([
      ['safety', 'Pred obnovením „Opravená gramatika“'],
      ['named', 'Opravená gramatika'],
      ['auto', 'Automatická záloha'],
    ])
    expect((await call('list_snapshots', { target: { kind: 'project', id: project.id } })).snapshots).toEqual([])
  })

  it('reads a draft snapshot with the read tools, naming its draft', async () => {
    const { project, draftId, target } = await draftWithHistory()
    const [safety, named] = (await call('list_snapshots', { target })).snapshots
    const namedTarget = { kind: 'snapshot', id: named.id }

    const part = await call('get_part', { target: namedTarget, part: 'grammarRules' })
    expect(part.target).toMatchObject({ kind: 'snapshot', id: named.id, projectId: project.id, draftId, snapshotKind: 'named' })
    expect(part.value).toBe(FIXED)
    expect((await call('get_part', { target: { kind: 'snapshot', id: safety.id }, part: 'grammarRules' })).value).toBe('E -> id id')
    expect((await call('get_ll_table', { target: namedTarget })).conflicts).toEqual([])
    expect((await call('simulate_ll', { target: namedTarget, input: 'id + id' })).ok).toBe(true)
    expect((await call('export', { target: namedTarget, kind: 'll-c' })).text).toContain('N_')
  })

  it('draft snapshots stay read-only for agents', async () => {
    const { draftId, target } = await draftWithHistory()
    const [safety] = (await call('list_snapshots', { target })).snapshots
    const before = h.store.getDraft(draftId)
    for (const [tool, args] of [
      ['set_grammar_rules', { text: 'E -> x' }],
      ['set_relation', { stack: 'id', input: '+', relation: '>' }],
      ['relabel_draft', { label: 'x' }],
      ['discard_draft', {}],
    ] as const) {
      expect((await call(tool, { target: { kind: 'snapshot', id: safety.id }, ...args })).error).toMatch(/snapshot.*cannot be changed/i)
    }
    expect(h.store.getDraft(draftId)).toEqual(before)
    expect(h.store.getSnapshot(safety.id)!.data.ll.grammar).toBe('E -> id id')
    const { result } = await h.rpc('tools/list')
    const names = (result.tools as { name: string }[]).map((t) => t.name)
    expect(names.filter((n) => /snapshot|restore/.test(n))).toEqual(['list_snapshots'])
  })
})
